using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using TrueReplayer.Controllers;
using TrueReplayer.Models;

namespace TrueReplayer.Services
{
    /// <summary>
    /// The example macros that ship inside the app (decision 4 of the interface swap plan): the same
    /// package the manual offers for download, generated by tools\ExampleProfiles and embedded as a
    /// resource. Read-only: "Use this example" copies one into the library, into the Examples folder,
    /// and nothing is ever imported on its own.
    /// </summary>
    public static class ExampleLibrary
    {
        public const string FolderName = "Examples";
        private const string ResourceName = "TrueReplayer.Examples.trprofile";

        public sealed record ExampleInfo(string Name, string? Description, List<string> Tags, string? IconEmoji, int ActionCount, List<string> Runs);

        /// <summary>
        /// The package, parsed fresh on every call. ConfirmImportAsync rewrites the RunProfile keys
        /// inside the envelope's own action lists when it renames a sub-profile, so a cached envelope
        /// would carry one copy's renames into the next. Null when the resource is missing or unreadable.
        /// </summary>
        public static ProfileExportEnvelope? Load()
        {
            using var stream = typeof(ExampleLibrary).Assembly.GetManifestResourceStream(ResourceName);
            if (stream == null) return null;
            using var reader = new StreamReader(stream);
            var (envelope, error) = ProfileController.ParseImportEnvelope(reader.ReadToEnd());
            return error == ImportParseError.None ? envelope : null;
        }

        public static List<ExampleInfo> List()
        {
            var envelope = Load();
            if (envelope == null) return new();
            var names = new HashSet<string>(envelope.Profiles.Select(p => p.Name), StringComparer.Ordinal);
            return envelope.Profiles
                .Select(p => new ExampleInfo(p.Name, p.Description, p.Tags ?? new(), p.IconEmoji, p.Actions.Count, RunsOf(p, names)))
                .ToList();
        }

        /// <summary>
        /// A package with the example and every example it runs by name, transitively (18 runs 18b),
        /// in package order and organized into the Examples folder. Null when there is no such example.
        /// </summary>
        public static ProfileExportEnvelope? PackageFor(string name)
        {
            var envelope = Load();
            if (envelope == null) return null;
            var byName = envelope.Profiles.ToDictionary(p => p.Name, StringComparer.Ordinal);
            if (!byName.ContainsKey(name)) return null;

            var names = new HashSet<string>(byName.Keys, StringComparer.Ordinal);
            var wanted = new HashSet<string>(StringComparer.Ordinal);
            var pending = new Stack<string>();
            pending.Push(name);
            while (pending.Count > 0)
            {
                var next = pending.Pop();
                if (!wanted.Add(next)) continue;
                foreach (var called in RunsOf(byName[next], names)) pending.Push(called);
            }

            var profiles = envelope.Profiles.Where(p => wanted.Contains(p.Name)).ToList();
            return new ProfileExportEnvelope
            {
                Version = envelope.Version,
                ExportedAt = envelope.ExportedAt,
                Profiles = profiles,
                Organization = new ProfileExportOrganization
                {
                    Folders = new()
                    {
                        new ProfileFolder
                        {
                            Name = FolderName,
                            Color = envelope.Organization?.Folders.FirstOrDefault()?.Color ?? "#9B7BFF",
                            Items = profiles.Select(p => p.Name).ToList(),
                        },
                    },
                },
            };
        }

        // The other examples a profile runs by name, through its RunProfile rows.
        private static List<string> RunsOf(ProfileExportEntry profile, HashSet<string> examples) =>
            profile.Actions
                .Where(a => a.ActionType == "RunProfile" && examples.Contains(a.Key))
                .Select(a => a.Key)
                .Distinct(StringComparer.Ordinal)
                .ToList();
    }
}
